CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Pedidos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Numero" character varying(20) NOT NULL,
    "Cliente" character varying(120) NOT NULL,
    "Status" character varying(20) NOT NULL,
    "CriadoEm" timestamp with time zone NOT NULL,
    "Total" numeric(18,2) NOT NULL,
    "EnderecoEntrega_Cep" character varying(8) NOT NULL,
    "EnderecoEntrega_Cidade" character varying(80) NOT NULL,
    "EnderecoEntrega_Logradouro" character varying(150) NOT NULL,
    "EnderecoEntrega_Uf" character varying(2) NOT NULL,
    "Metadados" jsonb NOT NULL,
    CONSTRAINT "PK_Pedidos" PRIMARY KEY ("Id")
);

CREATE TABLE "ItensPedido" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PedidoId" integer NOT NULL,
    "Produto" character varying(120) NOT NULL,
    "Quantidade" integer NOT NULL,
    "PrecoUnitario" numeric(18,2) NOT NULL,
    CONSTRAINT "PK_ItensPedido" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ItensPedido_Pedidos_PedidoId" FOREIGN KEY ("PedidoId") REFERENCES "Pedidos" ("Id") ON DELETE CASCADE
);

CREATE INDEX "IX_ItensPedido_PedidoId" ON "ItensPedido" ("PedidoId");

CREATE INDEX "IX_Pedidos_CriadoEm_Id" ON "Pedidos" ("CriadoEm" DESC, "Id" DESC);

CREATE UNIQUE INDEX "IX_Pedidos_Numero" ON "Pedidos" ("Numero");

CREATE INDEX "IX_Pedidos_Status_CriadoEm_Id" ON "Pedidos" ("Status", "CriadoEm" DESC, "Id" DESC);

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
